// Akıllı sokak lambası: gece kısık yanar, hareket olunca bir süre tam parlar.
const int ISIK_PIN = A0;   // LDR modülü AO (karanlıkta değer yükselir)
const int PIR_PIN = 2;     // PIR OUT
const int LAMBA_PIN = 9;   // PWM pini

const int GECE_ESIK = 700;                  // karanlık değeri bunu aşınca gece
const int KISIK = 40;                       // gece bekleme parlaklığı (0-255)
const int TAM = 255;                        // hareket olunca parlaklık
const unsigned long TAM_SURE_MS = 10000;    // son hareketten sonra tam parlak kalma süresi

bool hareketGoruldu = false;
unsigned long sonHareket = 0;
int sonParlaklik = -1;

void setup() {
  Serial.begin(9600);
  pinMode(PIR_PIN, INPUT);
  pinMode(LAMBA_PIN, OUTPUT);
  Serial.println("Hazir. Gercek PIR icin 30 saniye isinma gerekir.");
}

void loop() {
  int karanlik = analogRead(ISIK_PIN);  // 0-1023
  bool gece = karanlik > GECE_ESIK;

  // Hareketi yalnız gece say; gündüz geçen biri lambayı yakmaz.
  if (gece && digitalRead(PIR_PIN) == HIGH) {
    hareketGoruldu = true;
    sonHareket = millis();
  }
  bool tamParlak = hareketGoruldu && millis() - sonHareket < TAM_SURE_MS;

  int parlaklik = 0;
  if (gece) parlaklik = tamParlak ? TAM : KISIK;
  analogWrite(LAMBA_PIN, parlaklik);

  // Yalnız durum değişince yaz.
  if (parlaklik != sonParlaklik) {
    sonParlaklik = parlaklik;
    Serial.print("Karanlik: ");
    Serial.print(karanlik);
    Serial.print("  Lamba: ");
    if (parlaklik == 0) Serial.println("KAPALI");
    else if (parlaklik == TAM) Serial.println("TAM");
    else Serial.println("KISIK");
  }
  delay(100);
}
